using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
public sealed class NoteRevision {public string id="",noteId="",title="",project="",body="",saved="";public bool trashed;}
internal static class NoteHistory {
 const int MaxBytes=2*1024*1024;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};
 internal static Dictionary<string,NotePage> Snapshot(Data data){return data.pages.ToDictionary(n=>n.id,n=>Json.Deserialize<NotePage>(Json.Serialize(n)));}
 internal static void Validate(Data data){if(data.noteHistory==null)data.noteHistory=new List<NoteRevision>();if(data.noteHistory.Count>100||data.noteHistory.Any(r=>r==null||String.IsNullOrWhiteSpace(r.id)||r.id.Length>100||String.IsNullOrWhiteSpace(r.noteId)||r.noteId.Length>100||(r.title??"").Length>200||(r.project??"").Length>80||(r.body??"").Length>300000||(r.saved??"").Length>80)||data.noteHistory.Select(r=>r.id).Distinct().Count()!=data.noteHistory.Count||Encoding.UTF8.GetByteCount(Json.Serialize(data.noteHistory))>MaxBytes)throw new InvalidDataException("Historique des notes invalide ou trop volumineux.");}
 internal static void Capture(Data data,Dictionary<string,NotePage> previous){if(previous==null)return;foreach(var entry in previous){var old=entry.Value;var current=data.pages.FirstOrDefault(n=>n.id==entry.Key);if(current!=null&&current.title==old.title&&current.body==old.body&&current.project==old.project&&current.trashed==old.trashed)continue;data.noteHistory.Insert(0,new NoteRevision{id=Guid.NewGuid().ToString(),noteId=old.id,title=old.title,project=old.project,body=old.body,trashed=old.trashed,saved=DateTime.Now.ToString("o")});}var count=new Dictionary<string,int>();data.noteHistory=data.noteHistory.Where(r=>{int n;count.TryGetValue(r.noteId,out n);count[r.noteId]=n+1;return n<15;}).Take(100).ToList();while(data.noteHistory.Count>0&&Encoding.UTF8.GetByteCount(Json.Serialize(data.noteHistory))>MaxBytes)data.noteHistory.RemoveAt(data.noteHistory.Count-1);}
 internal static void Restore(Store store,string revisionId){var r=store.Value.noteHistory.FirstOrDefault(v=>v.id==revisionId);if(r==null)throw new InvalidOperationException("Cette version n’est plus disponible.");PersonalWorkflows.Change(store,()=>{var n=store.Value.pages.FirstOrDefault(p=>p.id==r.noteId);if(n==null){n=new NotePage{id=r.noteId};store.Value.pages.Add(n);}n.title=r.title;n.body=r.body;n.project=r.project;n.trashed=false;n.updated=DateTime.Now.ToString("o");});}
}
internal sealed partial class ModernWorkspace {
 void NoteHistoryPage(StackPanel body){body.Children.Add(T("Les versions précédentes sont conservées à chaque enregistrement qui modifie une note. Restaurer garde aussi la version actuelle dans l’historique.",12,Muted,new Thickness(0,0,0,18)));var query=new TextBox{ToolTip="Rechercher une ancienne note",MaxLength=180};body.Children.Add(query);var list=new StackPanel{Margin=new Thickness(0,12,0,0)};body.Children.Add(list);Action render=delegate{list.Children.Clear();foreach(var r in store.Value.noteHistory.Where(r=>(r.title+" "+r.project).IndexOf(query.Text,StringComparison.CurrentCultureIgnoreCase)>=0)){var revision=r;var panel=new StackPanel();DateTime saved;panel.Children.Add(T((DateTime.TryParse(r.saved,out saved)?saved.ToString("dd/MM/yyyy HH:mm:ss"):r.saved)+" · "+r.project,11,Muted,new Thickness(0,0,0,10)));panel.Children.Add(Btn("Consulter cette version",()=>OpenNoteRevision(revision),false,true));var card=Card(r.title,panel);card.Margin=new Thickness(0,0,0,12);list.Children.Add(card);}if(list.Children.Count==0)list.Children.Add(T("Aucune ancienne version pour le moment.",13,Muted));};query.TextChanged+=delegate{render();};render();body.Children.Add(T("Jusqu’à 15 versions par note, 100 versions au total et 2 Mo d’historique. Les sauvegardes complètes conservent cet historique.",11,Muted,new Thickness(0,16,0,0)));}
 void OpenNoteRevision(NoteRevision revision){if(!FlushDeskNotes())return;StackPanel body,actions;var w=Dialog("Ancienne version · "+revision.title,out body,out actions,700);body.Children.Add(T(revision.saved+" · "+revision.project,11,Muted));var text=new TextBox{Text=revision.body,IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Height=390};body.Children.Add(text);var error=T("",12,Accent);body.Children.Add(error);actions.Children.Add(Btn("Fermer",delegate{w.Close();},false,true));actions.Children.Add(Btn("Restaurer cette version",delegate{try{NoteHistory.Restore(store,revision.id);FinishFinanceDialog(w);}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);Refresh();}
}
